import 'dart:io';

import 'package:path/path.dart' as p;
import 'package:yaml/yaml.dart';

import 'config.dart';
import 'generated_assets.dart';
import 'usage_scanner.dart';

/// Finds the assets that nothing in the project refers to.
///
/// An asset counts as used when its accessor is read anywhere outside the
/// generated file, when the `values` of the class holding it is read, when its
/// path appears as a string literal, or when a configuration file of the
/// project root names it. Everything else is reported. In an app, the code of
/// a file no entry point reaches does not count, see
/// [UnusedAssetsConfig.entryPoints].
final class UnusedAssetsFinder {
  /// Creates a finder for a project at [root].
  const UnusedAssetsFinder({
    required this.config,
    required this.root,
  });

  /// Settings of the search.
  final UnusedAssetsConfig config;

  /// Project root the paths of [config] are resolved against.
  final String root;

  /// File generated by flutter_gen.
  File get generatedFile => File(p.join(root, config.generated));

  /// Searches the project, in the order of the generated file.
  UnusedAssetsReport find() {
    final packageName = _packageName();
    final assets = readGeneratedAssets(
      generatedFile.readAsStringSync(),
      packageName: packageName,
    );

    final usages = scanUsages(
      root: root,
      directories: config.scan,
      skip: config.generated,
      packageName: packageName,
      entryPoints: config.entryPoints,
    );

    final declared = _configReferences();

    final unused = <GeneratedAsset>[];
    final reachedByValues = <GeneratedAsset>[];

    for (final asset in assets) {
      if (config.ignores(asset.path) ||
          usages.accessors.contains(asset.accessor) ||
          usages.strings.contains(asset.path) ||
          declared.contains(asset.path)) {
        continue;
      }

      if (usages.valuesTargets.contains(asset.container)) {
        reachedByValues.add(asset);
        continue;
      }

      unused.add(asset);
    }

    return UnusedAssetsReport(
      unused: unused,
      reachedByValues: reachedByValues,
      deadFiles: usages.deadFiles,
      missingFiles: usages.missingFiles,
    );
  }

  String? _packageName() {
    final pubspec = File(p.join(root, 'pubspec.yaml'));
    if (!pubspec.existsSync()) return null;

    if (loadYaml(pubspec.readAsStringSync()) case {'name': final String name}) {
      return name;
    }
    return null;
  }

  /// Assets referenced by the configuration files of the project root.
  ///
  /// Every `*.yaml` and `*.yml` next to the `pubspec.yaml` is read, so the
  /// configs of the tooling that live in a file of their own —
  /// `flutter_native_splash.yaml` and the like — count as usages too.
  Set<String> _configReferences() {
    final references = <String>{};

    for (final entity in Directory(root).listSync(followLinks: false)) {
      if (entity is! File) continue;

      final extension = p.extension(entity.path).toLowerCase();
      if (extension != '.yaml' && extension != '.yml') continue;

      references.addAll(configReferences(
        entity.readAsStringSync(),
        skipDeclaredAssets: p.basename(entity.path) == 'pubspec.yaml',
        sourceUrl: Uri.file(p.basename(entity.path)),
      ));
    }

    return references;
  }

  /// Deletes the files of [assets], along with their resolution variants.
  ///
  /// The generated file is left alone: it is regenerated by flutter_gen, and
  /// editing it by hand would only be undone on the next run.
  DeleteReport delete(List<GeneratedAsset> assets) {
    final report = plan(assets);

    for (final variant in report.variants) {
      File(p.join(root, variant)).deleteSync();
    }
    for (final asset in report.assets) {
      File(p.join(root, asset.path)).deleteSync();
    }

    return report;
  }

  /// What [delete] would remove for [assets]: the files that exist on disk and
  /// their resolution variants.
  DeleteReport plan(List<GeneratedAsset> assets) => DeleteReport(
    assets: <GeneratedAsset>[
      for (final asset in assets)
        if (File(p.join(root, asset.path)).existsSync()) asset,
    ],
    variants: <String>[
      for (final asset in assets) ..._variantsOf(asset.path),
    ],
  );

  /// Resolution variants of [assetPath], as paths relative to the project root.
  ///
  /// Flutter keeps them in a directory named after the ratio next to the asset
  /// — `images/2.0x/logo.png` for `images/logo.png`. They carry no accessor of
  /// their own, so nothing would ever report them and they would stay behind as
  /// garbage once the asset they belong to is gone.
  List<String> _variantsOf(String assetPath) {
    final directory = Directory(p.join(root, p.dirname(assetPath)));
    if (!directory.existsSync()) return const <String>[];

    final name = p.basename(assetPath);
    final variants = <String>[
      for (final entity in directory.listSync(followLinks: false))
        if (entity is Directory && _ratio.hasMatch(p.basename(entity.path)))
          if (File(p.join(entity.path, name)).existsSync())
            p.relative(p.join(entity.path, name), from: root)
                .replaceAll(r'\', '/'),
    ];
    variants.sort();

    return variants;
  }

  static final RegExp _ratio = RegExp(r'^\d+(\.\d+)?x$');
}

/// Outcome of a search.
final class UnusedAssetsReport {
  /// Creates a report.
  const UnusedAssetsReport({
    required this.unused,
    required this.reachedByValues,
    required this.deadFiles,
    required this.missingFiles,
  });

  /// Assets nothing refers to.
  final List<GeneratedAsset> unused;

  /// Assets nothing names, kept only because the `values` of the class holding
  /// them is read.
  ///
  /// Such a read uses the whole class at once, so a genuinely unused asset
  /// among them cannot be told apart from a used one and stays out of [unused].
  /// Worth knowing: it is the one place where the search is blind by design.
  final List<GeneratedAsset> reachedByValues;

  /// Files under `lib` no entry point reaches, relative to the project root.
  ///
  /// They are dead code, so what they refer to did not count.
  final List<String> deadFiles;

  /// Project files the search for dead code needed and did not find, relative
  /// to the project root. When there are any, no file was taken for dead.
  final List<String> missingFiles;

  /// Names of the classes whose `values` is read, without repetition.
  List<String> get containersReachedByValues {
    final containers = <String>{
      for (final asset in reachedByValues) asset.container,
    }.toList();
    containers.sort();

    return containers;
  }
}

/// Outcome of a deletion.
final class DeleteReport {
  /// Creates a report.
  const DeleteReport({
    required this.assets,
    required this.variants,
  });

  /// Assets whose file was on disk and has been deleted.
  final List<GeneratedAsset> assets;

  /// Resolution variants deleted along with them, relative to the project root.
  final List<String> variants;
}
